use super::*;
fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=1);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn retire<T:crate::retirement::RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64,maximum:u64){let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..maximum{if owner.terminal_is_empty(){break}let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.step(RetainedCloneGrant{maximum_items:1,..*bank}).unwrap());let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(bank,fuel,p,owner.last_turn_work());}assert!(owner.terminal_is_empty());}
#[test]fn actual_builder_normal_births_preserve_null_rows_header_moves_and_every_cancel_frontier(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let maximum=s["maximumTurns"].as_u64().unwrap();for count in law["counts"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;for cut in law["cancelPrefixes"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap())).chain([None]){let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let mut owner=PersistentListBuilder::new(count);let mut row=None;let mut adopted=0;let mut finishing=false;let mut injected=false;
 for at in 0..maximum{if cut==Some(at)||owner.output_ready(){break}if owner.accepts_row()&&adopted<count{if row.is_none(){let turn=SealedShared::admit(adopted as u64,crate::shared_issuance::SharedIssuer::owned(),RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(value,p)=turn.result.map_err(|(e,_)|e).unwrap();row=Some(value);debit(&mut bank,&mut fuel,p,work);}let pointer=row.as_ref().unwrap().identity();let denied=owner.adopt(&mut row,RetainedCloneGrant{maximum_items:0,..bank});assert_eq!(denied.work,0);assert!(denied.result.unwrap().is_none());assert_eq!(row.as_ref().unwrap().identity(),pointer);let turn=owner.adopt(&mut row,RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let p=turn.result.unwrap().unwrap();assert_eq!(p.copied_bytes,0);debit(&mut bank,&mut fuel,p,work);adopted+=1;continue}if owner.accepts_row()&&!finishing{let turn=owner.finish(RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let p=turn.result.unwrap().unwrap();assert_eq!(p.copied_bytes,0);debit(&mut bank,&mut fuel,p,work);finishing=true;assert!(owner.finishing());let cached=owner.finish(Default::default());assert_eq!(cached.work,0);assert_eq!(cached.result.unwrap().unwrap(),Default::default());continue}
 let d=owner.demand().unwrap();for axis in 0..5{let mut g=RetainedCloneGrant{maximum_items:1,..bank};match axis{0=>g.maximum_items=0,1 if d.copy_bytes>0=>g.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes>0=>g.maximum_capacity_bytes=d.capacity_bytes-1,3 if d.release_bytes>0=>g.maximum_release_bytes=d.release_bytes-1,4 if d.depth>0=>g.maximum_depth=d.depth-1,_=>continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.advance(g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(owner.demand().unwrap(),d);}
 if d.capacity_bytes>0&&!injected{let pointers:Vec<_>=owner.rows.iter().map(|v|v.as_ref().map(SealedShared::identity)).collect();let((turn,attempts),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||owner.advance(RetainedCloneGrant{maximum_items:1,..bank})));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);fuel-=turn.work;assert!(turn.result.is_err());assert_eq!(owner.rows.iter().map(|v|v.as_ref().map(SealedShared::identity)).collect::<Vec<_>>(),pointers);injected=true;continue}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.advance(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert_eq!(p.copied_bytes,0);debit(&mut bank,&mut fuel,p,work);
 }
 if cut.is_none(){assert!(owner.output_ready());let(output,p)=owner.take(RetainedCloneGrant{maximum_items:1,..bank}).unwrap().unwrap();debit(&mut bank,&mut fuel,p,1);let actual:Vec<u64>=output.iter().copied().collect();assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value((0..count as u64).collect::<Vec<_>>()).unwrap());retire(output,&mut bank,&mut fuel,maximum);}if let Some(value)=row.take(){retire(value,&mut bank,&mut fuel,maximum);}owner.begin_close();for _ in 0..maximum{if owner.terminal_is_empty(){break}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||owner.close_step(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,work);}assert!(owner.terminal_is_empty());}}
}
